75	    /** Add a claim for a person; a missing date takes the sheet's today. Its due-by is fixed now: its
76	     *  date plus the person's own terms, else the terms in force on that date for the person's grade then. A negative amount is a
77	     *  correction and must name a SETTLED claim of the person it corrects. */
78	    @Transactional
79	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
80	            String corrects) {
81	        Person person = person(sheetId, personId);
82	        corrects = numberOf(corrects);
83	        LocalDate on = date != null ? date : sheets.today(sheetId);
84	        refuseClosed(sheetId, on);
85	        refuseRetired(person, on);
86	        refuseBadCorrection(sheetId, personId, amount, corrects);
87	        LocalDate dueBy = on.plusDays(termsFor(sheetId, person, on));
88	        Claim added = claims.saveAndFlush(new Claim(sheetId, personId, scaled(amount), on, dueBy, noteOf(note),
89	                corrects));
90	        log(sheetId, user, person, added);
91	        record("CLAIM_ADDED", sheetId, user, person, added);
92	        return added;
93	    }
