95	    /** Change a DRAFT claim's amount, date and note; a missing date takes the sheet's today. Any
96	     *  other claim is refused: an OPEN one is changed by voiding it and adding a new one. */
97	    @Transactional
98	    public Claim update(String sheetId, String user, Long personId, Long id, BigDecimal amount, LocalDate date,
99	            String note, String corrects) {
100	        Person person = person(sheetId, personId);
101	        corrects = numberOf(corrects);
102	        Claim claim = claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
103	                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
104	        if (claim.getStatus() != ClaimStatus.DRAFT) {
105	            throw new ClaimNotEditableException(claim.getStatus());
106	        }
107	        LocalDate on = date != null ? date : sheets.today(sheetId);
108	        refuseClosed(sheetId, claim.getDate());
109	        refuseClosed(sheetId, on);
110	        refuseRetired(person, on);
111	        refuseBadCorrection(sheetId, personId, amount, corrects);
112	        claim.setAmount(scaled(amount));
113	        claim.setCorrects(corrects);
114	        claim.setDate(on);
115	        claim.setNote(noteOf(note));
116	        Claim saved = claims.saveAndFlush(claim);
117	        record("CLAIM_EDITED", sheetId, user, person, saved);
118	        return saved;
119	    }
