121	    /** Move a claim to a new status; a change its status does not allow, or one the sheet's
122	     *  permission matrix does not let the user's role make, is refused, as is the user who opened a
123	     *  claim settling it. A clerk settling a claim whose due is above the clerk limit
124	     *  leaves it PENDING a steward's approval instead. */
125	    @Transactional
126	    public Claim changeStatus(String sheetId, String user, Long personId, Long id, ClaimStatus to) {
127	        Person person = person(sheetId, personId);
128	        // Lock the sheet first, so a claim opened at the same moment elsewhere waits and the claim
129	        // read below is its latest state.
130	        if (to == ClaimStatus.OPEN) {
131	            sheets.lock(sheetId);
132	        }
133	        Claim claim = claim(sheetId, personId, id);
134	        settings.refuseUnless(sheetId, user, switch (to) {
135	            case OPEN -> Permission.OPEN;
136	            case SETTLED -> Permission.SETTLE;
137	            case VOID -> Permission.VOID;
138	            case DRAFT, PENDING -> throw new StatusChangeRefusedException(claim.getStatus(), to);
139	        });
140	        refuseClosed(sheetId, claim.getDate());
141	        // A SETTLED claim is voided only by a steward, within the void window of its settlement.
142	        boolean reversing = to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
143	        if (reversing) {
144	            refuseLateOrUnstewardedVoid(sheetId, user, claim);
145	        } else if (!claim.getStatus().canMoveTo(to)) {
146	            throw new StatusChangeRefusedException(claim.getStatus(), to);
147	        }
148	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
149	            throw new OwnClaimSettleRefusedException(user);
150	        }
151	        if (to == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(sheetId))) {
152	            throw new StatusChangeRefusedException(claim.getStatus(), to);
153	        }
154	        // Taken while the claim is still OPEN, so a settled due freezes in the late charge it has
155	        // gathered by then.
156	        BigDecimal due = to == ClaimStatus.SETTLED ? dueOf(sheetId, person, claim) : null;
157	        if (to == ClaimStatus.SETTLED) {
158	            refuseUnproved(sheetId, claim, due);
159	        }
160	        if (to == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, due)) {
161	            to = ClaimStatus.PENDING;
162	        }
163	        claim.setStatus(to);
164	        if (to == ClaimStatus.OPEN) {
165	            claim.setNumber(nextNumber(sheetId, claim.getDate()));
166	            claim.setOpenedBy(user);
167	        } else if (to == ClaimStatus.SETTLED) {
168	            claim.setSettledDue(due);
169	        }
170	        Claim saved = claims.saveAndFlush(claim);
171	        log(sheetId, user, person, saved);
172	        String event = switch (to) {
173	            case OPEN -> "CLAIM_OPENED";
174	            case PENDING -> "CLAIM_PENDING";
175	            case SETTLED -> "CLAIM_SETTLED";
176	            case VOID -> "CLAIM_VOIDED";
177	            case DRAFT -> throw new IllegalStateException("A claim never returns to DRAFT");
178	        };
179	        String line = line(event, sheetId, user, person, saved, saved.getNumber());
180	        if (to == ClaimStatus.SETTLED) {
181	            line += " due=" + settledDueText(saved);
182	        } else if (reversing) {
183	            line += " reversed=" + settledDueText(saved);
184	        }
185	        audit.recordOnCommit(line);
186	        if (to == ClaimStatus.SETTLED) {
187	            notifyWatchers(sheetId, user, person, saved);
188	        }
189	        return saved;
190	    }
