192	    /** Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it
193	     *  the claim counts in no total, is not overdue, cannot be settled and no statement binds it. A
194	     *  claim that is not OPEN, a date not after today, or a claim dated in a closed period, is refused. */
195	    @Transactional
196	    public Claim defer(String sheetId, String user, Long personId, Long id, LocalDate until) {
197	        Person person = person(sheetId, personId);
198	        Claim claim = claim(sheetId, personId, id);
199	        refuseClosed(sheetId, claim.getDate());
200	        if (claim.getStatus() != ClaimStatus.OPEN) {
201	            throw new DeferRefusedException("A " + claim.getStatus() + " claim cannot be deferred");
202	        }
203	        if (!until.isAfter(sheets.today(sheetId))) {
204	            throw new DeferRefusedException("A claim is deferred to a date after the sheet's today");
205	        }
206	        claim.setDeferredUntil(until);
207	        Claim saved = claims.saveAndFlush(claim);
208	        audit.recordOnCommit(line("CLAIM_DEFERRED", sheetId, user, person, saved, saved.getNumber())
209	                + " until=" + until);
210	        return saved;
211	    }
