213	    /** A split: the claim that kept the rest of its amount, and the claim split off it. */
214	    public record Split(Claim kept, Claim added) {
215	    }
216	
217	    /** Split an amount off an OPEN claim: it keeps the rest of its amount and loses any figure a
218	     *  statement bound it to, and a new OPEN claim of the split-off amount, with the same date and
219	     *  note, the next number, opened by the user and due by its date plus the terms in force on it,
220	     *  is listed under the person naming the claim it was split from. A claim that is not OPEN, one
221	     *  deferred, one dated in a closed period, an amount not above 0.00 and below the claim's, or a
222	     *  user whose role may not open a claim, is refused. */
223	    @Transactional
224	    public Split split(String sheetId, String user, Long personId, Long id, BigDecimal amount) {
225	        Person person = person(sheetId, personId);
226	        // Lock the sheet first, as opening does: the new claim takes the next number.
227	        sheets.lock(sheetId);
228	        Claim claim = claim(sheetId, personId, id);
229	        settings.refuseUnless(sheetId, user, Permission.OPEN);
230	        refuseClosed(sheetId, claim.getDate());
231	        if (claim.getStatus() != ClaimStatus.OPEN || claim.deferredOn(sheets.today(sheetId))) {
232	            throw new SplitRefusedException("A " + claim.getStatus() + " claim cannot be split");
233	        }
234	        BigDecimal part = scaled(amount);
235	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
236	            throw new SplitRefusedException("A claim is split by an amount above 0.00 and below its own");
237	        }
238	        claim.setAmount(claim.getAmount().subtract(part));
239	        claim.unbind();
240	        Claim kept = claims.saveAndFlush(claim);
241	        LocalDate on = kept.getDate();
242	        LocalDate dueBy = on.plusDays(termsFor(sheetId, person, on));
243	        Claim added = claims.saveAndFlush(Claim.splitOff(kept, part, dueBy, nextNumber(sheetId, on), user));
244	        log(sheetId, user, person, added);
245	        audit.recordOnCommit(line("CLAIM_SPLIT", sheetId, user, person, kept, kept.getNumber())
246	                + " into=" + added.getNumber());
247	        record("CLAIM_OPENED", sheetId, user, person, added);
248	        return new Split(kept, added);
249	    }
