251	    /** A steward approves a PENDING claim: it is SETTLED, its due frozen at this moment. Anyone else,
252	     *  the user who opened it, or a claim that is not PENDING, is refused. */
253	    @Transactional
254	    public Claim approve(String sheetId, String user, Long personId, Long id) {
255	        Person person = person(sheetId, personId);
256	        Claim claim = pending(sheetId, user, personId, id, ClaimStatus.SETTLED);
257	        if (user.equals(claim.getOpenedBy())) {
258	            throw new OwnClaimSettleRefusedException(user);
259	        }
260	        BigDecimal due = dueOf(sheetId, person, claim);
261	        refuseUnproved(sheetId, claim, due);
262	        claim.setSettledDue(due);
263	        claim.setStatus(ClaimStatus.SETTLED);
264	        Claim saved = claims.saveAndFlush(claim);
265	        log(sheetId, user, person, saved);
266	        audit.recordOnCommit(line("CLAIM_APPROVED", sheetId, user, person, saved, saved.getNumber())
267	                + " due=" + settledDueText(saved));
268	        notifyWatchers(sheetId, user, person, saved);
269	        return saved;
270	    }
