272	    /** Add a proof to a claim: its proofs count rises by one. A SETTLED or VOID claim, or one dated in
273	     *  a closed period, is refused. */
274	    @Transactional
275	    public Claim addProof(String sheetId, String user, Long personId, Long id) {
276	        Person person = person(sheetId, personId);
277	        Claim claim = claim(sheetId, personId, id);
278	        refuseClosed(sheetId, claim.getDate());
279	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
280	            throw new ProofRefusedException(claim.getStatus());
281	        }
282	        claim.addProof();
283	        Claim saved = claims.saveAndFlush(claim);
284	        audit.recordOnCommit(line("CLAIM_PROOF_ADDED", sheetId, user, person, saved, saved.getNumber())
285	                + " proofs=" + saved.getProofs());
286	        return saved;
287	    }
