289	    /** A steward rejects a PENDING claim with a reason: it is OPEN again, bound again by the person's
290	     *  last statement if that statement bound it. Anyone else, or a claim that is not PENDING, is
291	     *  refused. */
292	    @Transactional
293	    public Claim reject(String sheetId, String user, Long personId, Long id, String reason) {
294	        Person person = person(sheetId, personId);
295	        Claim claim = pending(sheetId, user, personId, id, ClaimStatus.OPEN);
296	        claim.setStatus(ClaimStatus.OPEN);
297	        Claim saved = claims.saveAndFlush(claim);
298	        log(sheetId, user, person, saved);
299	        audit.recordOnCommit(line("CLAIM_REJECTED", sheetId, user, person, saved, saved.getNumber())
300	                + " reason=" + reason.trim());
301	        return saved;
302	    }
