304	    /** A steward re-settles a SETTLED claim: its settled due is frozen again at the figure it would
305	     *  have today as an OPEN claim bound by no statement (today's rates, grades, floor and late
306	     *  charge), and its status log gains a SETTLED line. Anyone else, a claim that is not SETTLED, or
307	     *  one dated in a closed period, is refused. */
308	    @Transactional
309	    public Claim resettle(String sheetId, String user, Long personId, Long id) {
310	        Person person = person(sheetId, personId);
311	        Claim claim = claim(sheetId, personId, id);
312	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
313	            throw new ResettleRefusedException(user);
314	        }
315	        if (claim.getStatus() != ClaimStatus.SETTLED) {
316	            throw new StatusChangeRefusedException(claim.getStatus(), ClaimStatus.SETTLED);
317	        }
318	        refuseClosed(sheetId, claim.getDate());
319	        String old = settledDueText(claim);
320	        BigDecimal figure = liveFigureOf(sheetId, person, claim);
321	        claim.setSettledDue(figure == null ? null : floored(sheetId, claim, figure.add(lateChargeOf(sheetId, claim, figure, true))));
322	        Claim saved = claims.saveAndFlush(claim);
323	        log(sheetId, user, person, saved);
324	        audit.recordOnCommit(line("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber())
325	                + " old=" + old + " new=" + settledDueText(saved));
326	        notifyWatchers(sheetId, user, person, saved);
327	        return saved;
328	    }
