330	    /** A user whose role the sheet's permission matrix lets reassign (by the standing rule a steward)
331	     *  moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its
332	     *  number and date, loses any figure a statement bound it to (live again until its new person's
333	     *  next statement), and is listed as its new person's newest claim. Anyone else, a SETTLED or VOID
334	     *  claim, a correction (it names a claim of its own person), a claim dated in a closed period, or
335	     *  a move to the same person or to one retired before the claim's date, is refused. */
336	    @Transactional
337	    public Claim reassign(String sheetId, String user, Long personId, Long id, Long toPersonId) {
338	        Person from = person(sheetId, personId);
339	        Person to = person(sheetId, toPersonId);
340	        Claim claim = claim(sheetId, personId, id);
341	        if (!settings.allows(sheetId, user, Permission.REASSIGN)) {
342	            throw new ReassignRefusedException(user);
343	        }
344	        if (!claim.getStatus().canReassign()) {
345	            throw new MoveRefusedException("A " + claim.getStatus() + " claim cannot move to another person");
346	        }
347	        if (from.getId().equals(to.getId())) {
348	            throw new MoveRefusedException("The claim is already " + to.getName() + "'s");
349	        }
350	        if (claim.isCorrection()) {
351	            throw new MoveRefusedException("A correction stays with the person whose claim it corrects");
352	        }
353	        refuseClosed(sheetId, claim.getDate());
354	        refuseRetired(to, claim.getDate());
355	        claim.setPersonId(to.getId());
356	        claim.unbind();
357	        claims.saveAndFlush(claim);
358	        claims.relist(claim.getId());
359	        Claim saved = claim(sheetId, to.getId(), id);
360	        audit.recordOnCommit(line("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber())
361	                + " from=" + from.getName() + " to=" + to.getName());
362	        return saved;
363	    }
