376	    /** The status each of the sheet's claims had at the end of a day, by claim id, as its status log
377	     *  records it: the last status it moved to on or before that day. A claim added after it has none. */
378	    public Map<Long, ClaimStatus> statusesAsOf(String sheetId, LocalDate day) {
379	        Map<Long, ClaimStatus> statuses = new HashMap<>();
380	        for (ClaimLogEntry entry : logs.findBySheetIdOrderByIdAsc(sheetId)) {
381	            if (!entry.getOn().isAfter(day)) {
382	                statuses.put(entry.getClaimId(), entry.getStatus());
383	            }
384	        }
385	        return statuses;
386	    }
