388	    /** Log the status a claim has just moved to (or been added in): by whom, on the sheet's today, and
389	     *  its due as it is now. */
390	    private void log(String sheetId, String user, Person person, Claim claim) {
391	        BigDecimal due = dueOf(sheetId, person, claim);
392	        logs.save(new ClaimLogEntry(sheetId, claim.getId(), claim.getStatus(), user, sheets.today(sheetId),
393	                due != null ? due.toPlainString() : NO_RATE));
394	    }
