396	    /** A SETTLED claim is voided only by a steward, and only while the sheet's today is within
397	     *  {@value #VOID_WINDOW_DAYS} days of the date its status log last records it SETTLED. */
398	    private void refuseLateOrUnstewardedVoid(String sheetId, String user, Claim claim) {
399	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
400	            throw new VoidRefusedException(user + " is not a steward: only a steward voids a settled claim");
401	        }
402	        LocalDate settledOn = logs.findByClaimIdOrderByIdAsc(claim.getId()).stream()
403	                .filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
404	                .map(ClaimLogEntry::getOn)
405	                .reduce((first, last) -> last)
406	                .orElseThrow(() -> new VoidRefusedException("Claim " + claim.getId() + " has no settlement"));
407	        if (sheets.today(sheetId).isAfter(settledOn.plusDays(VOID_WINDOW_DAYS))) {
408	            throw new VoidRefusedException("A settled claim is voided within " + VOID_WINDOW_DAYS
409	                    + " days of its settlement on " + settledOn);
410	        }
411	    }
