413	    /** The PENDING claim a steward approves or rejects; refused when it is not PENDING, dated in a
414	     *  closed period, or the user is not a steward. */
415	    private Claim pending(String sheetId, String user, Long personId, Long id, ClaimStatus to) {
416	        Claim claim = claim(sheetId, personId, id);
417	        refuseClosed(sheetId, claim.getDate());
418	        if (claim.getStatus() != ClaimStatus.PENDING) {
419	            throw new StatusChangeRefusedException(claim.getStatus(), to);
420	        }
421	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
422	            throw new ApprovalRefusedException(user);
423	        }
424	        return claim;
425	    }
