432	    private static String settledDueText(Claim claim) {
433	        return claim.getSettledDue() != null ? claim.getSettledDue().toPlainString() : NO_RATE;
434	    }
435	
436	    /** The number a claim opened now takes: under period numbering (set, and the sheet's today on or
437	     *  after it) the next within the period its date falls in, <period>-<n>, or X-<n> when it falls
438	     *  in none; otherwise the sheet's next sheet-wide number. Taken with the sheet locked. */
439	    private String nextNumber(String sheetId, LocalDate date) {
440	        LocalDate from = settings.periodNumberingFrom(sheetId);
441	        if (from == null || sheets.today(sheetId).isBefore(from)) {
442	            return String.valueOf(sheets.nextClaimNumber(sheetId));
443	        }
444	        String prefix = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
445	                .filter(period -> period.contains(date))
446	                .findFirst().map(Period::getName).orElse(NO_PERIOD) + "-";
447	        long last = claims.numbers(sheetId).stream()
448	                .filter(number -> number.startsWith(prefix))
449	                .map(number -> number.substring(prefix.length()))
450	                .filter(n -> n.matches("\\d{1,18}"))
451	                .mapToLong(Long::parseLong)
452	                .max().orElse(0);
453	        return prefix + (last + 1);
454	    }
455	
456	    /** The figure a claim shows: the due fixed when it was settled, else (unless it is PENDING, which
457	     *  no statement binds) the figure its person's last statement bound it to, else its due at the
458	     *  person's grade rate; null when it has none. */
459	    public BigDecimal figureOf(String sheetId, Person person, Claim claim) {
460	        if (claim.getSettledDue() != null) {
461	            return claim.getSettledDue();
462	        }
463	        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue() : liveFigureOf(sheetId, person, claim);
464	    }
465	
466	    /** The due a claim shows: a settled claim's frozen due; otherwise the greater of the sheet's floor in
467	     *  force on its date (none for a correction) and its figure plus its late charge (none while it is
468	     *  deferred: it is not overdue then); null when it has no figure. */
469	    public BigDecimal dueOf(String sheetId, Person person, Claim claim) {
470	        if (claim.getSettledDue() != null) {
471	            return claim.getSettledDue();
472	        }
473	        BigDecimal figure = figureOf(sheetId, person, claim);
474	        boolean open = claim.getStatus().isOpen() && !claim.deferredOn(sheets.today(sheetId));
475	        return figure == null ? null : floored(sheetId, claim, figure.add(lateChargeOf(sheetId, claim, figure, open)));
476	    }
477	
478	    /** A due raised to the sheet's floor in force on the claim's date, unless the claim is a correction. */
479	    private BigDecimal floored(String sheetId, Claim claim, BigDecimal due) {
480	        return claim.isCorrection() ? due : due.max(settings.floor(sheetId, claim.getDate()));
481	    }
482	
483	    /** The late charge on a claim with a figure: none unless it is OPEN or PENDING and overdue (its due-by is
484	     *  before the sheet's today) or a correction, else the late percent of the figure for every 30-day
485	     *  boundary it is overdue past (its due-by plus 30, 60, 90 ... days), the late percent in force on that
486	     *  boundary date of the figure, rounded to two decimals as the claim's date decides (see roundingOf), the
487	     *  charges added up. Never bound by a statement: it follows the
488	     *  sheet's today. Whether the claim counts as open is given, so a re-settle can charge a SETTLED
489	     *  claim as if it were still OPEN. */
490	    private BigDecimal lateChargeOf(String sheetId, Claim claim, BigDecimal figure, boolean open) {
491	        BigDecimal none = BigDecimal.ZERO.setScale(2);
492	        if (!open || claim.isCorrection()) {
493	            return none;
494	        }
495	        long days = ChronoUnit.DAYS.between(claim.getDueBy(), sheets.today(sheetId));
496	        if (days < 30) {
497	            return none;
498	        }
499	        RoundingMode rounding = roundingOf(sheetId, claim);
500	        BigDecimal charge = none;
501	        for (long boundary = 1; boundary <= days / 30; boundary++) {
502	            BigDecimal pct = settings.latePct(sheetId, claim.getDueBy().plusDays(30 * boundary));
503	            if (pct.signum() != 0) {
504	                charge = charge.add(figure.multiply(pct).movePointLeft(2).setScale(2, rounding));
505	            }
506	        }
507	        return charge;
508	    }
509	
510	    /** The due on a claim at the rate in force on the claim's date for the person's grade in force
511	     *  on the claim's date: amount times rate
512	     *  divided by 100, rounded to two decimals as the claim's date decides (see roundingOf); the floor is
513	     *  not applied here (see dueOf); null when no rate applies. */
514	    private BigDecimal liveFigureOf(String sheetId, Person person, Claim claim) {
515	        BigDecimal amount = claim.getAmount();
516	        RoundingMode rounding = roundingOf(sheetId, claim);
517	        return rates.rateOn(sheetId, grades.gradeOn(person.getId(), claim.getDate()), claim.getDate())
518	                .map(Rate::getRate)
519	                .map(rate -> amount.multiply(rate).movePointLeft(2).setScale(2, rounding))
520	                .orElse(null);
521	    }
522	
523	    /** The date a claim's live figures round by: its own, or for a correction the date of the claim
524	     *  it corrects. */
525	    public LocalDate roundsBy(String sheetId, Claim claim) {
526	        if (!claim.isCorrection() || claim.getCorrects() == null) {
527	            return claim.getDate();
528	        }
529	        return claims.findBySheetIdAndPersonIdAndNumber(sheetId, claim.getPersonId(), claim.getCorrects())
530	                .map(Claim::getDate).orElse(claim.getDate());
531	    }
532	
533	    /** How a claim's live figures round: by the sheet's policy date against the date it rounds by. */
534	    private RoundingMode roundingOf(String sheetId, Claim claim) {
535	        return settings.roundingOn(sheetId, roundsBy(sheetId, claim));
536	    }
537	
538	    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit; a due of n/a
539	     *  is within any limit, and a steward settles anything. */
540	    private boolean overClerkLimit(String sheetId, String user, BigDecimal due) {
541	        BigDecimal limit = settings.clerkLimit(sheetId);
542	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
543	            return false;
544	        }
545	        return settings.roleOf(sheetId, user) == Role.CLERK;
546	    }
547	
548	    /** A claim whose due is above the proof threshold in force on its date cannot be settled or
549	     *  approved while it has no proofs; a due of n/a, or no threshold, asks for none. */
550	    private void refuseUnproved(String sheetId, Claim claim, BigDecimal due) {
551	        BigDecimal threshold = settings.proofThreshold(sheetId, claim.getDate());
552	        if (claim.getProofs() == 0 && threshold != null && due != null && due.compareTo(threshold) > 0) {
553	            throw new ProofRequiredException(due, threshold);
554	        }
555	    }
556	
557	    /** A negative amount (a correction) must name the number of a SETTLED claim of the same person;
558	     *  any other amount names none. */
559	    private void refuseBadCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
560	        if (amount.signum() >= 0) {
561	            if (corrects != null) {
562	                throw new CorrectionRefusedException("Only a negative amount corrects a claim");
563	            }
564	            return;
565	        }
566	        if (corrects == null) {
567	            throw new CorrectionRefusedException("A negative amount must name the claim it corrects");
568	        }
569	        boolean settled = claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
570	                .map(c -> c.getStatus() == ClaimStatus.SETTLED).orElse(false);
571	        if (!settled) {
572	            throw new CorrectionRefusedException("No SETTLED claim " + corrects + " of this person to correct");
573	        }
574	    }
575	
576	    /** A claim dated inside a closed period cannot be added, edited, opened, settled or voided. */
577	    private void refuseClosed(String sheetId, LocalDate date) {
578	        if (periods.closedOn(sheetId, date)) {
579	            throw new PeriodClosedException("A claim dated " + date + " falls in a closed period");
580	        }
581	    }
582	
583	    /** A claim dated after its person's retirement date cannot be added or moved there. */
584	    private static void refuseRetired(Person person, LocalDate date) {
585	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
586	            throw new PersonRetiredException(person.getName(), person.getRetiredFrom(), date);
587	        }
588	    }
589	
590	    private Person person(String sheetId, Long personId) {
591	        return people.findByIdAndSheetId(personId, sheetId)
592	                .orElseThrow(() -> new NoSuchElementException("No person " + personId + " on sheet " + sheetId));
593	    }
594	
595	    /** One NOTIFY line for each user watching the claim's person, in the order they started watching. */
596	    private void notifyWatchers(String sheetId, String user, Person person, Claim claim) {
597	        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
598	            audit.recordOnCommit("NOTIFY sheet=" + sheetId + " by=" + user + " user=" + watch.getUser()
599	                    + " person=" + person.getName() + " number=" + claim.getNumber());
600	        }
601	    }
602	
603	    private void record(String event, String sheetId, String user, Person person, Claim claim) {
604	        record(event, sheetId, user, person, claim, claim.getNumber());
605	    }
606	
607	    /** One audit line about a claim; a claim with a number carries it at the end. */
608	    private void record(String event, String sheetId, String user, Person person, Claim claim, String number) {
609	        audit.recordOnCommit(line(event, sheetId, user, person, claim, number));
610	    }
611	
612	    private static String line(String event, String sheetId, String user, Person person, Claim claim, String number) {
613	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
614	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
615	                + (number != null ? " number=" + number : "");
616	    }
617	
618	    private static BigDecimal scaled(BigDecimal amount) {
619	        return amount.setScale(2, RoundingMode.UNNECESSARY);
620	    }
621	
622	    /** A claim number as typed: trimmed, null when blank. */
623	    private static String numberOf(String number) {
624	        return number == null || number.isBlank() ? null : number.trim();
625	    }
626	
627	    private static String noteOf(String note) {
628	        return note == null ? "" : note.trim();
629	    }
630	
631	    /** The terms in days a claim of the person dated on a date takes: the person's own, else their
632	     *  grade's in force then, else the sheet's. */
633	    private int termsFor(String sheetId, Person person, LocalDate on) {
634	        return person.getTerms() != null ? person.getTerms()
635	                : settings.termsFor(sheetId, grades.gradeOn(person.getId(), on), on);
636	    }
637	}
